STYLE='''
:root{color-scheme:dark;--bg:#0c0a12;--card:#151120;--gold:#e5b95c;--text:#f5edd6;--muted:#b9b0cb;--line:#40334e}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at top,#241936,var(--bg) 650px);color:var(--text);font:16px/1.65 system-ui,-apple-system,"Segoe UI",sans-serif}a{color:var(--gold);text-underline-offset:4px}button{font:inherit;cursor:pointer}h1,h2,h3{font-family:Georgia,serif;font-weight:500;line-height:1.2}h1{font-size:clamp(2.4rem,6vw,4.8rem);max-width:850px;margin:20px 0}h2{font-size:clamp(1.7rem,4vw,2.5rem)}h3{font-size:1.15rem;color:var(--gold)}p{max-width:900px}nav,.container{max-width:1200px;margin:auto;padding:24px}nav{display:flex;flex-wrap:wrap;justify-content:space-between;gap:14px;border-bottom:1px solid var(--line)}nav>div{display:flex;gap:18px;flex-wrap:wrap}nav a{min-height:44px;display:inline-flex;align-items:center;text-decoration:none;font-size:.85rem}.brand{color:var(--text);font-weight:750;letter-spacing:.08em}header{padding:28px 0 16px}.eyebrow{font-size:.75rem;letter-spacing:.12em;text-transform:uppercase;color:var(--gold)}.intro{font-size:1.1rem;color:var(--muted);max-width:800px}.notice{padding:18px 22px;background:var(--card);border:1px solid var(--line);border-radius:12px;font-size:.88rem;color:var(--muted)}.jump{display:flex;flex-wrap:wrap;gap:8px;margin:24px 0 40px}.jump a,.btn{border:1px solid var(--line);border-radius:8px;padding:10px 14px;background:var(--card);text-decoration:none;display:inline-flex;align-items:center;min-height:44px;color:var(--gold);font-size:.85rem}.btn.primary{background:var(--gold);color:var(--bg);font-weight:650}.deck-section{padding:32px 0 48px;border-top:1px solid var(--line);scroll-margin-top:20px}.deck-heading{display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;align-items:baseline}.deck-heading h2{margin:12px 0}.status{font-size:.75rem;color:var(--gold);letter-spacing:.05em}.stats{display:flex;flex-wrap:wrap;gap:10px;margin:18px 0 24px}.stats span{padding:8px 12px;border:1px solid var(--line);border-radius:8px;font-size:.8rem}.deck-grid{display:grid;grid-template-columns:1fr 1fr;gap:32px}.plan p{font-size:.95rem;color:var(--muted);margin:6px 0 18px}.plan h3{margin:0}.list-panel{padding:22px;background:var(--card);border:1px solid var(--line);border-radius:12px;min-width:0}.list-panel summary{cursor:pointer;color:var(--gold);font-weight:600;padding:8px 0}.list-panel textarea{display:block;width:100%;height:380px;resize:vertical;padding:12px;background:var(--bg);color:var(--text);border:1px solid var(--line);border-radius:6px;font:14px/1.6 ui-monospace,Consolas,monospace;margin:10px 0}.actions{display:flex;flex-wrap:wrap;gap:8px}.copy-status{min-height:1.8em;font-size:.8rem;color:var(--muted)}.curve{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0}.curve span{font-size:.75rem;color:var(--muted)}.table-scroll{overflow:auto;border:1px solid var(--line);border-radius:10px}table{border-collapse:collapse;width:100%;font-size:.88rem}td,th{padding:14px 16px;text-align:left;border-bottom:1px solid var(--line);vertical-align:top}th{color:var(--gold);font-weight:600}tr:last-child td{border:0}.prose-section{padding:28px 0;border-top:1px solid var(--line)}.prose-section li{margin:14px 0;max-width:900px;color:var(--muted)}footer{padding:30px 0;border-top:1px solid var(--line);font-size:.8rem;color:var(--muted)}:focus-visible{outline:3px solid var(--gold);outline-offset:4px}.skip{position:absolute;top:5px;left:10px;padding:10px;background:var(--text);color:var(--bg);transform:translateY(-150%)}.skip:focus{transform:none}.muted{color:var(--muted);font-size:.85rem}label{display:block;font-size:.82rem;color:var(--muted)}@media(max-width:700px){nav,.container{padding:18px}.deck-grid{grid-template-columns:1fr;gap:16px}header{padding-top:16px}.list-panel{padding:16px}.deck-section{padding:24px 0 32px}td,th{padding:12px}.intro{font-size:1rem}.notice{padding:16px}.jump{margin-bottom:24px}.deck-heading{gap:0}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}'''
JS='''document.querySelectorAll('[data-copy]').forEach(button=>button.addEventListener('click',async()=>{const text=document.getElementById(button.dataset.copy);const status=document.getElementById(button.dataset.copy+'-status');try{await navigator.clipboard.writeText(text.value);status.textContent=document.documentElement.lang==='it'?'Lista copiata':'List copied';}catch{text.closest('details').open=true;text.focus();text.select();status.textContent=document.documentElement.lang==='it'?'Testo selezionato: usa Ctrl+C o il menu Copia.':'Text selected: use Ctrl+C or the Copy menu.';}}));'''


def render(decks, results, lang):
    t=COPY[lang]; other='tournament-decks.en.html' if lang=='it' else 'tournament-decks.html'
    sections=[]
    for deck in decks:
        cards=deck['cards']; id_=deck['id']; curve=Counter()
        for c in cards: curve[c['cost']]+=c['quantity']
        plans=''.join(f'<h3>{escape(label)}</h3><p>{escape(body)}</p>' for label,body in zip(t['plan'],deck['plan'][lang]))
        n_ink=sum(c['quantity'] for c in cards if c['inkable']); hyperia=sum(c['quantity'] for c in cards if c['set']==14)
        sections.append(f'''<article class="deck-section" id="{id_}"><div class="deck-heading"><div><span class="status">{escape(t['themed'] if deck['status']=='themed' else t['evidence'])}</span><h2>{escape(deck['name'])}</h2></div><span class="muted">{escape(deck['inks'])}</span></div><p class="muted">{escape(deck['result'])} · {escape(deck['author'])}<br><a href="{escape(deck['source'],quote=True)}">{t['source']}</a></p><div class="stats"><span>60 {t['cards']}</span><span>{n_ink}/60 {t['ink']}</span><span>{hyperia}/60 {t['hyperia']}</span><span>Core · 2026-11-04</span></div><div class="deck-grid"><div class="plan">{plans}</div><div class="list-panel"><div class="actions"><a class="btn primary" href="deck-lab.html?deck={id_}">{t['lab']}</a><a class="btn" href="decks/{id_}.txt" download>{t['download']}</a></div><p class="muted">Duels.ink / Dreamborn · 60 {t['cards']}</p><details><summary>{t['details']}</summary><label for="list-{id_}">{t['form']}</label><textarea readonly spellcheck="false" id="list-{id_}">{escape(deck_text(deck))}</textarea></details><button class="btn" type="button" data-copy="list-{id_}">{t['copy']}</button><p class="copy-status" role="status" id="list-{id_}-status"></p><div class="curve">{''.join(f'<span>{cost}: <b>{qty}</b></span>' for cost,qty in sorted(curve.items()))}</div><p class="muted">Costo stampato / Printed cost : copies</p></div></div></article>''')
    sim_rows=''.join(f'<tr><td><a href="#{d["id"]}">{escape(d["name"])}</a></td><td>{results[d["id"]]["opening"]["one_and_two"]:.1%}</td><td>{results[d["id"]]["mulligan"]["one_and_two"]:.1%}</td></tr>' for d in decks)
    swiss=''.join(f'<tr><td>{p:.0%}</td><td>{swiss_probability(p):.1%}</td></tr>' for p in (.5,.55,.6))
    page=f'''<!DOCTYPE html><html lang="{lang}"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta name="description" content="{escape(t['intro'],quote=True)}"><title>Lorcana · {t['title']}</title><style>{STYLE}</style></head><body><a class="skip" href="#main">Skip / Vai al contenuto</a><nav aria-label="Main navigation"><a class="brand" href="index.html">LORCANA COMPANION</a><div><a href="deck-lab.html">Deck Lab</a><a href="collector-vault.html">Collector Vault</a><a href="{other}" lang="{'en' if lang=='it' else 'it'}">{'English' if lang=='it' else 'Italiano'}</a></div></nav><main id="main" class="container" tabindex="-1"><header><span class="eyebrow">Core · 5 decklists · 2026-11-04</span><h1>{t['lead']}</h1><p class="intro">{t['intro']}</p></header><p class="notice">{t['notice']}</p><p><a class="btn" href="decks/tournament-lists.zip" download>ZIP · 5 decklists</a></p><div class="jump">{''.join(f'<a href="#{d["id"]}">{escape(d["name"])}</a>' for d in decks)}<a href="#steelsong">Steelsong</a><a href="#simulation">{t['sim']}</a></div>{''.join(sections)}<section class="prose-section" id="steelsong"><h2>{t['steelsong']}</h2><p>{t['steelbody']}</p><p>{t['steelcombo']}</p><p class="notice">{t['steelnotes']}</p></section><section class="prose-section" id="practice"><h2>{t['practice']}</h2><ol>{''.join('<li>'+escape(x)+'</li>' for x in t['training'])}</ol></section><section class="prose-section" id="torino"><h2>{t['event']}</h2><p>{t['eventbody']}</p><p>{t['schedule']}</p><a href="https://github.com/MRJonam91/disney-lorcana-companion/blob/master/docs/research/torino-tournament-context.md">{t['research']}</a></section><section class="prose-section" id="simulation"><h2>{t['sim']}</h2><p>{t['simbody']}</p><p class="muted">{t['joint']}</p><div class="table-scroll" tabindex="0" role="region" aria-label="Opening hand experiment"><table><thead><tr><th>Deck</th><th>{t['opening']}</th><th>{t['after']}</th></tr></thead><tbody>{sim_rows}</tbody></table></div><p><a href="data/tournament-simulations.json" download>JSON · seed + results</a> · <a href="https://github.com/MRJonam91/disney-lorcana-companion/blob/master/tools/deck_catalog.py">Python source</a></p><h3>{t['swiss']}</h3><p>{t['swissbody']}</p><div class="table-scroll" tabindex="0" role="region" aria-label="Theoretical six-match model"><table><thead><tr><th>{t['swissp']}</th><th>{t['swissr']}</th></tr></thead><tbody>{swiss}</tbody></table></div></section><section class="prose-section"><h2>{t['research']}</h2><p><a href="https://github.com/MRJonam91/disney-lorcana-companion/blob/master/docs/research/hyperia-card-verification.md">Hyperia · Core · Guitar / Ernesto · Toulouse / Ward</a></p><p><a href="https://chatgpt.com/share/6aebb14d-2114-83eb-a12d-333586112e50">Analisi condivisa / Shared analysis</a> · <a href="https://disneylorcana.com/en/resources/">Official resources</a></p><p class="muted">{t['privacy']}</p></section></main><footer class="container">Unofficial community companion · Disney / Ravensburger marks remain with their owners. <a href="https://github.com/MRJonam91/disney-lorcana-companion">GitHub</a></footer><script>{JS}</script></body></html>'''
    return page+'\n'


def main():
    parser=argparse.ArgumentParser(); parser.add_argument('--simulate',action='store_true'); parser.add_argument('--check',action='store_true'); args=parser.parse_args()
    data=(ROOT/'data/tournament-decks.json').read_text(encoding='utf-8-sig').encode('utf8'); decks=json.loads(data); validate_catalog(decks)
    digest=sha256(data).hexdigest(); sim_path=ROOT/'data/tournament-simulations.json'
    if args.simulate:
        output={'schema_version':1,'catalog_sha256':digest,'model':'opening-hand-only','seed':20261104,'trials_per_deck':200000,'results':{}}
        for d in decks:
            output['results'][d['id']]=opening_metrics(d)
            print('Simulated',d['id'],flush=True)
        sim_path.write_text(json.dumps(output,indent=2)+'\n',encoding='utf8',newline='\n')
    sims=json.loads(sim_path.read_text(encoding='utf8'))
    if sims['catalog_sha256']!=digest: raise ValueError('Catalog changed: rerun with --simulate')
    artifacts={Path('tournament-decks.html'):render(decks,sims['results'],'it'),Path('tournament-decks.en.html'):render(decks,sims['results'],'en')}
    for d in decks: artifacts[Path('decks')/(d['id']+'.txt')]=deck_text(d)
    js_decks=[{k:d[k] for k in ('id','name','source','cards')} for d in decks]
    artifacts[Path('data/tournament-decks.js')]='window.LORCANA_TOURNAMENT_DECKS = '+json.dumps(js_decks,ensure_ascii=False,separators=(',',':'))+';\n'
    for name,text in artifacts.items():
        path=ROOT/name
        if args.check:
            if not path.exists() or path.read_text(encoding='utf8')!=text:raise ValueError(f'Generated file is stale: {name}')
        else:
            path.parent.mkdir(exist_ok=True,parents=True);path.write_text(text,encoding='utf8',newline='\n')
    archive=BytesIO()
    with ZipFile(archive,'w') as package:
        files={d['id']+'.txt':deck_text(d) for d in decks}
        files['SOURCES.txt']='Lorcana deck lists / Liste mazzi - snapshot 2026-11-04\n\n'+''.join(d['name']+' - '+d['author']+'\n'+d['source']+'\n\n' for d in decks)+'No card art or card text is included. No price or performance guarantee.\n'
        for filename,body in sorted(files.items()):
            info=ZipInfo(filename,date_time=(1980,1,1,0,0,0));info.create_system=3;info.compress_type=ZIP_DEFLATED
            package.writestr(info,body.encode('utf8'))
    archive_path=ROOT/'decks/tournament-lists.zip'
    if args.check:
        if not archive_path.exists():raise ValueError('Deck ZIP is missing')
        validate_deck_archive(archive_path.read_bytes(), files)
    else:archive_path.write_bytes(archive.getvalue())
    print(('Checked' if args.check else 'Generated'),len(artifacts),'artifacts for',len(decks),'validated decks')


if __name__=='__main__':main()
